export type Role = "system" | "user" | "assistant" | "tool";

/**
 * Structured tool call generated by the model.
 */
export interface ToolCall {
  id: string;
  name: string;
  arguments: Record<string, unknown>;
  rawArguments?: string;
}

/**
 * Unified message representation across all providers and tools.
 */
export interface Message {
  role: Role;
  content: string | null;
  toolCalls?: ToolCall[];
  toolCallId?: string;
  toolName?: string;
}

/**
 * Tool declaration using JSON Schema for parameters.
 */
export interface ToolDefinition {
  name: string;
  description: string;
  parameters: {
    type: "object";
    properties: Record<string, unknown>;
    required?: string[];
    [key: string]: unknown;
  };
}

/**
 * Options passed to model generation requests.
 */
export interface SendMessageOptions {
  tools?: ToolDefinition[];
  temperature?: number;
  maxTokens?: number;
  systemInstruction?: string;
  signal?: AbortSignal;
}

export type FinishReason =
  | "stop"
  | "tool_calls"
  | "length"
  | "content_filter"
  | "error";

export interface TokenUsage {
  promptTokens: number;
  completionTokens: number;
  totalTokens: number;
}

/**
 * Normalized response from a model adapter.
 */
export interface ModelResponse {
  content: string;
  toolCalls?: ToolCall[];
  finishReason?: FinishReason;
  usage?: TokenUsage;
}

/**
 * Incremental chunk yielded during streaming.
 */
export interface StreamChunk {
  deltaContent?: string;
  deltaToolCall?: Partial<ToolCall> & { index?: number };
  finishReason?: FinishReason;
}

/**
 * Universal model adapter contract.
 */
export interface ModelAdapter {
  readonly providerName: string;
  sendMessage(
    messages: Message[],
    options?: SendMessageOptions
  ): Promise<ModelResponse>;
  streamMessage?(
    messages: Message[],
    options?: SendMessageOptions
  ): AsyncIterable<StreamChunk>;
}



